require_once __DIR__.'/includes/bootstrap.php';require_role(['Administrator']);$pdo=db();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$values=['sacco_name'=>trim($_POST['sacco_name']??''),'contact_email'=>trim($_POST['contact_email']??''),'contact_phone'=>trim($_POST['contact_phone']??''),'timezone'=>'Africa/Nairobi','currency'=>'KES'];if($values['sacco_name']==='')$errors[]='SACCO name is required.';if($values['contact_email']!==''&&!filter_var($values['contact_email'],FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid contact email.';if(!$errors){$st=$pdo->prepare('INSERT INTO system_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');foreach($values as $k=>$v)$st->execute([$k,$v]);audit_log($pdo,'settings.updated','settings',null,'Updated SACCO settings.');flash('System settings saved.');header('Location: settings.php');exit;}}
$settings=[];foreach(fetch_all($pdo,'SELECT setting_key,setting_value FROM system_settings') as $s)$settings[$s['setting_key']]=$s['setting_value'];
