echo '<section class="card" style="max-width:760px"><div class="card-head"><div><h2>Organisation profile</h2><p>Configure the identity shown across your operations workspace.</p></div></div><form method="post">'.csrf_field().'<div class="form-grid"><div class="field"><label>SACCO / organisation name</label><input name="sacco_name" value="'.e($settings['sacco_name']??'Nairobi – Kitengela SACCO').'" required></div><div class="field"><label>Contact email</label><input type="email" name="contact_email" value="'.e($settings['contact_email']??'').'"></div><div class="field"><label>Contact phone</label><input name="contact_phone" value="'.e($settings['contact_phone']??'').'"></div><div class="field"><label>Timezone</label><input value="Africa/Nairobi (EAT)" disabled></div><div class="field"><label>Currency</label><input value="Kenyan Shilling (KSh)" disabled></div><div class="field"><label>Session inactivity timeout</label><input value="30 minutes (configured)" disabled></div></div><div class="form-actions"><button type="submit">Save settings</button></div></form></section><section class="card" style="max-width:760px"><h2>Operational safeguards</h2><p class="muted">Backups must be stored outside the public web root and scheduled using the host operating system. Before production use, configure HTTPS, restrict database privileges, rotate credentials and test a restore procedure.</p><div class="notice success" style="margin:0"><span>✓</span><div>Application timezone is configured for East Africa. Display currency is Kenyan Shillings.</div></div></section>';
page_footer();
